import heapq

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(r, c):
        return abs(r - goal_row) + abs(c - goal_col)

    visited = set()
    priority_queue = [(heuristic(start_row, start_col), 0, start_row, start_col, [start])]
    heapq.heapify(priority_queue)

    while priority_queue:
        _, _, r, c, path = heapq.heappop(priority_queue)
        if (r, c) == (goal_row, goal_col):
            return path
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                new_path = path + [(nr, nc)]
                heapq.heappush(priority_queue, (len(new_path) + heuristic(nr, nc), len(new_path), nr, nc, new_path))

    return []

