def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(current, path, depth_limit):
        if current == goal:
            return path + [current]
        if depth_limit <= 0:
            return None
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_pos = (current[0] + dr, current[1] + dc)
            if is_valid(next_pos) and next_pos not in path:
                result = dfs(next_pos, path + [current], depth_limit - 1)
                if result:
                    return result
        return None

    if not is_valid(start) or not is_valid(goal) or start == goal:
        return [start] if start == goal else []

    max_depth = 2 * max(rows, cols)
    for depth in range(1, max_depth + 1):
        result = dfs(start, [], depth)
        if result:
            return result
    return []

